//! The ECM fonts (§6 "Fonts are part of the protocol").
//!
//! The guest lays out text, so the guest toolkit, the Java rasterizer and the
//! client all measure glyphs from these same tables, generated by
//! `scripts/gen-ui-fonts.py` from the glyph sources in
//! `assets/evanscomputermod/ecm_fonts/`.
//!
//! * `ui` — ECM's own proportional pixel font, designed at 8 lu (small) and
//!   12 lu (regular). Supported sizes: 8, 12, 16 (small ×2), 24 (regular ×2),
//!   32 (small ×4).
//! * `mono` — the 8×16 terminal font. Sizes 16 and 32.
//!
//! A size is the line height in lu. Each glyph is a bitmap `height` rows tall
//! drawn at its pen position; its advance is `width + spacing` (×scale). The
//! width of a string is the sum of its characters' advances (one glyph per
//! Unicode scalar value, no kerning). A character without a glyph draws as
//! the design's fixed-width box.

use crate::Font;

mod data {
    include!("fonts_data.rs");
}

pub use data::{METRICS_HASH, METRICS_VERSION};

/// One designed size of a font.
pub struct Design {
    pub name: &'static str,
    /// Protocol `Font` code.
    pub font: u8,
    pub base_size: u8,
    /// Rows per glyph = line height at scale 1.
    pub height: u8,
    /// Rows above the baseline.
    pub ascent: u8,
    /// Blank columns after each glyph.
    pub spacing: u8,
    /// (codepoint, width, offset into `rows`), sorted by codepoint.
    pub glyphs: &'static [(u32, u8, u16)],
    /// `height` u16 rows per glyph; bit 0 is the leftmost column.
    pub rows: &'static [u16],
    pub missing_width: u8,
    pub missing_offset: u16,
}

/// A glyph's bitmap at scale 1.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct Glyph {
    pub width: u8,
    pub advance: u8,
    /// `height` rows, bit 0 = leftmost column.
    pub rows: &'static [u16],
    /// False for the fixed-width "missing glyph" box.
    pub found: bool,
}

impl Design {
    pub fn glyph(&'static self, c: char) -> Glyph {
        let h = self.height as usize;
        match self.glyphs.binary_search_by_key(&(c as u32), |g| g.0) {
            Ok(i) => {
                let (_, w, off) = self.glyphs[i];
                Glyph { width: w, advance: w + self.spacing, rows: &self.rows[off as usize..off as usize + h], found: true }
            }
            Err(_) => {
                let off = self.missing_offset as usize;
                Glyph {
                    width: self.missing_width,
                    advance: self.missing_width + self.spacing,
                    rows: &self.rows[off..off + h],
                    found: false,
                }
            }
        }
    }
}

/// A font at one supported size: a design and a whole-number scale.
#[derive(Copy, Clone)]
pub struct Face {
    pub design: &'static Design,
    pub scale: u8,
    pub size: u8,
}

impl core::fmt::Debug for Face {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "Face({} x{})", self.design.name, self.scale)
    }
}

impl Face {
    /// Line height in lu (= the size).
    pub fn line_height(&self) -> i32 {
        self.design.height as i32 * self.scale as i32
    }
    /// Distance from the top of the line box to the baseline, in lu.
    pub fn ascent(&self) -> i32 {
        self.design.ascent as i32 * self.scale as i32
    }
    /// Advance of one character in lu.
    pub fn advance(&self, c: char) -> i32 {
        self.design.glyph(c).advance as i32 * self.scale as i32
    }
    /// Width of a single line of text in lu.
    pub fn text_width(&self, s: &str) -> i32 {
        s.chars().map(|c| self.design.glyph(c).advance as i32).sum::<i32>() * self.scale as i32
    }
    pub fn glyph(&self, c: char) -> Glyph {
        self.design.glyph(c)
    }
}

/// The face for `font` at `size`, or None if that size isn't supported.
pub fn face(font: Font, size: u8) -> Option<Face> {
    data::SIZES
        .iter()
        .find(|s| s.0 == font.code() && s.1 == size)
        .map(|s| Face { design: data::DESIGNS[s.2 as usize], scale: s.3, size })
}

/// Supported sizes of `font`, ascending.
pub fn sizes(font: Font) -> impl Iterator<Item = u8> {
    data::SIZES.iter().filter(move |s| s.0 == font.code()).map(|s| s.1)
}

/// Every design (in the order the metrics hash covers them).
pub fn designs() -> &'static [&'static Design] {
    data::DESIGNS
}

/// FNV-1a 32 over the tables, as `scripts/gen-ui-fonts.py` computes it.
/// Equal to [`METRICS_HASH`] unless the tables are corrupt.
pub fn compute_metrics_hash() -> u32 {
    let mut h: u32 = 0x811C_9DC5;
    let mut feed = |v: u32| {
        for b in v.to_le_bytes() {
            h = (h ^ b as u32).wrapping_mul(0x0100_0193);
        }
    };
    for d in data::DESIGNS {
        for v in [d.font as u32, d.base_size as u32, d.height as u32, d.ascent as u32, d.spacing as u32, d.missing_width as u32] {
            feed(v);
        }
        let h = d.height as usize;
        for r in &d.rows[d.missing_offset as usize..d.missing_offset as usize + h] {
            feed(*r as u32);
        }
        for &(cp, w, off) in d.glyphs {
            feed(cp);
            feed(w as u32);
            for r in &d.rows[off as usize..off as usize + h] {
                feed(*r as u32);
            }
        }
    }
    for s in data::SIZES {
        for v in [s.0, s.1, s.2, s.3] {
            feed(v as u32);
        }
    }
    h
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_match_their_hash() {
        assert_eq!(compute_metrics_hash(), METRICS_HASH);
    }

    #[test]
    fn sizes_map_to_designs() {
        let f = |font, size| face(font, size).map(|f| (f.design.name, f.scale));
        assert_eq!(f(Font::Ui, 8), Some(("ui-small", 1)));
        assert_eq!(f(Font::Ui, 12), Some(("ui-regular", 1)));
        assert_eq!(f(Font::Ui, 16), Some(("ui-small", 2)));
        assert_eq!(f(Font::Ui, 24), Some(("ui-regular", 2)));
        assert_eq!(f(Font::Ui, 32), Some(("ui-small", 4)));
        assert_eq!(f(Font::Mono, 16), Some(("mono", 1)));
        assert_eq!(f(Font::Mono, 32), Some(("mono", 2)));
        assert!(face(Font::Ui, 10).is_none() && face(Font::Mono, 12).is_none());
    }

    #[test]
    fn coverage_metrics_and_missing_box() {
        for size in [8, 12] {
            let fc = face(Font::Ui, size).unwrap();
            for c in (0x20u8..0x7F).chain(0xA0..=0xFF) {
                assert!(fc.glyph(c as char).found, "{} lacks {:?}", fc.design.name, c as char);
            }
            // Missing glyphs are a fixed box.
            let m = fc.glyph('\u{4e2d}');
            assert!(!m.found);
            assert_eq!(m.advance, fc.glyph('\u{30c6}').advance);
        }
        let mono = face(Font::Mono, 16).unwrap();
        for c in "Ag~é\u{4e2d}".chars() {
            assert_eq!(mono.advance(c), 8);
        }
        assert_eq!(face(Font::Mono, 32).unwrap().text_width("abc"), 48);
        // Regular: 'H' is 5 wide + 1 spacing; 'i' is 1 + 1.
        let r = face(Font::Ui, 12).unwrap();
        assert_eq!(r.text_width("Hi"), 8);
        assert_eq!(face(Font::Ui, 24).unwrap().text_width("Hi"), 16);
        assert_eq!(r.line_height(), 12);
        assert_eq!(r.ascent(), 9);
    }
}
